-- ----------------------------
-- Table structure for quiz_result
-- ----------------------------
DROP TABLE IF EXISTS `quiz_result`;
CREATE TABLE `quiz_result`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `openid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户openid',
  `questionnaire_id` bigint NOT NULL COMMENT '问卷ID',
  `answers` json NOT NULL COMMENT '用户答案，存储题目id和选项索引/分数',
  `score` int NOT NULL COMMENT '总得分',
  `max_score` int NULL DEFAULT NULL COMMENT '满分',
  `score_percent` int NULL DEFAULT NULL COMMENT '得分占比 0-100',
  `conclusion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '测评结论（如“轻度焦虑”）',
  `suggestions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '建议',
  `ai_chat_hint` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '给小爱的一句话开场',
  `ai_guidance` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'AI 生成的解读与建议（可空）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user`(`openid` ASC) USING BTREE,
  INDEX `idx_quiz`(`questionnaire_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '测评结果表' ROW_FORMAT = Dynamic;

