INSERT INTO `chat_history` VALUES (398, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '小爱暂时有点忙，请稍后再试。你也可以先去驿站模块看看文章、音乐或自我疗愈内容。', '2026-04-15 15:37:57');
INSERT INTO `chat_history` VALUES (399, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '？', '2026-04-15 15:38:03');
INSERT INTO `chat_history` VALUES (400, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '哈哈，抱歉抱歉～刚才好像系统有点小卡顿 😅\n\n我是小爱，你的校园心理陪伴助手。虽然我主要擅长倾听和聊天，但讲笑话嘛...我试试看！\n\n---\n\n**超长校园笑话来啦：**\n\n小明上课睡觉被老师叫起来回答问题。\n\n老师：\"小明，你来回答，这道题选什么？\"\n\n小明迷迷糊糊站起来：\"选...选C？\"\n\n老师：\"很好，坐下吧。\"\n\n同桌小声说：\"老师问的是\'你来回答一下这道题的解题思路是什么\'...\"\n\n小明：\"......\"\n\n老师：\"小明，那你解释一下为什么选C？\"\n\n小明灵机一动：\"因为A、B、D都不对！\"\n\n全班沉默三秒后爆笑。\n\n老师无奈地说：\"行吧，逻辑上没毛病。\"\n\n---\n\n怎么样，有没有冷到你？❄️\n\n有什么想聊的随时找我～', '2026-04-15 15:38:18');
INSERT INTO `chat_history` VALUES (401, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '再来一个长的故事', '2026-04-15 16:03:55');
INSERT INTO `chat_history` VALUES (402, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '好嘞，给你来一个长一点的～\n\n---\n\n**《图书馆奇遇记》**\n\n小李期末周去图书馆抢座位，早上六点就起床了，结果到了发现队伍已经排到门口了。\n\n好不容易挤进去，发现只剩一个位置，旁边坐着一个女生，桌上堆了八本书，占了大半个桌子。\n\n小李小心翼翼问：\"同学，这位置有人吗？\"\n\n女生头也不抬：\"有，我朋友。\"\n\n小李：\"那她人呢？\"\n\n女生：\"她...她去厕所了。\"\n\n小李只好站着等。\n\n等了半小时，没人来。\n\n一小时，还是没人来。\n\n两小时后，女生开始收拾东西准备走了。\n\n小李激动地问：\"你朋友不来了？\"\n\n女生淡定地说：\"我朋友今天没来图书馆。\"\n\n小李：\"？？？那你刚才...\"\n\n女生：\"哦，我怕你坐我旁边会打扰我学习。\"\n\n说完潇洒离去。\n\n小李愣在原地，旁边另一个同学拍拍他肩膀：\"兄弟，习惯就好，她每天都这样。\"\n\n---\n\n哈哈，有没有感同身受？😄\n\n还想听什么类型的？', '2026-04-15 16:04:08');
INSERT INTO `chat_history` VALUES (403, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '来个长故事', '2026-04-15 16:05:02');
