INSERT INTO `chat_history` VALUES (408, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '抱歉刚才的回复有点奇怪，让我重新来～\n\n你想听什么类型的故事呢？比如：\n\n- 🌸 温馨治愈的校园故事\n- 🌙 关于友情/成长的故事\n- 🍃 轻松有趣的小故事\n- 💫 带点奇幻色彩的故事\n\n或者你有什么特别想听的主题，也可以告诉我～小爱陪你聊聊 😊', '2026-04-15 16:05:54');
INSERT INTO `chat_history` VALUES (409, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '校园治愈故事', '2026-04-15 16:06:04');
INSERT INTO `chat_history` VALUES (410, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '好的，给你讲一个～\n\n---\n\n**《天台上的秘密花园》**\n\n高二那年，林小夏总是一个人躲到天台吃午饭。\n\n不是被排挤，只是她不太会聊天，每次和别人在一起都觉得尴尬。她觉得自己像一颗格格不入的螺丝钉。\n\n有一天，她发现天台角落里多了一盆小小的多肉植物，旁边压着一张纸条：\n\n*\"如果你也喜欢安静，可以帮我照顾它吗？——3班的某个人\"*\n\n她开始每天给它浇水。\n\n一周后，多肉旁边多了一盆绿萝，又一张纸条：\n\n*\"谢谢你。今天被老师批评了，但看到它长得很好，心情好多了。\"*\n\n林小夏第一次觉得，原来自己也可以被需要。\n\n后来，那个角落慢慢变成了一个小小的\"花园\"。她和那个\"3班的某个人\"用纸条交流着，分享着各自的小烦恼和小快乐。\n\n直到毕业那天，她才知道——那个人，是班里最安静的男生，和她一样，也曾觉得自己格格不入。\n\n---\n\n有时候，治愈不需要轰轰烈烈，只需要一个小小的连接 🌱\n\n喜欢这个故事吗？', '2026-04-15 16:06:14');
INSERT INTO `chat_history` VALUES (411, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '我刚完成了「症状自评量表（SCL-90）」，结果是「中度风险」（约 60%）。想请你帮我一起看看接下来可以怎么调整。', '2026-04-15 16:07:12');
