INSERT INTO `chat_history` VALUES (415, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '我刚完成了「症状自评量表（SCL-90）」，结果是「中度风险」（约 60%）。想请你帮我一起看看接下来可以怎么调整。', '2026-04-15 16:08:46');
INSERT INTO `chat_history` VALUES (416, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '你好呀，谢谢你愿意和我分享这个结果。能主动关注自己的心理状态，这本身就是很积极的一步 💙\n\n关于SCL-90的结果，我想先了解一下：\n\n**你现在的感觉怎么样？** 比如：\n- 最近有什么让你感到困扰或压力的事情吗？\n- 睡眠、食欲、情绪方面有没有什么变化？\n\n---\n\n在等待你回复的同时，分享几个通用的调整方向：\n\n1. **觉察而不评判** — 量表是参考工具，不是定论。中度风险提示\"需要关注\"，不代表有什么问题\n\n2. **生活基础调整** — 规律作息、适度运动、保持社交连接，这些对心理状态有稳定作用\n\n3. **找到情绪出口** — 写日记、和信任的人聊聊、或者继续和我聊都可以\n\n4. **必要时寻求专业支持** — 如果困扰持续或加重，学校心理咨询中心是很好的资源\n\n---\n\n你愿意多说说最近的情况吗？我们可以一起看看从哪里开始调整 😊', '2026-04-15 16:08:58');
INSERT INTO `chat_history` VALUES (417, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '来个长对话', '2026-04-15 16:12:28');
INSERT INTO `chat_history` VALUES (418, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '好的呀，我很乐意陪你慢慢聊 ☺️\n\n那我们从头开始，你方便的话可以和我分享：\n\n---\n\n**关于最近的状态：**\n\n- 这段时间，你过得怎么样？\n- 有没有什么特别的事情发生，或者一直压在心里的事？\n\n**关于量表本身：**\n\n- 做完这个测试后，你心里是什么感受？\n- 结果和你自己的感觉一致吗？\n\n---\n\n不用着急，想到什么就说什么，没有对错之分。\n\n我在这里，慢慢听你说 🌿', '2026-04-15 16:12:36');
INSERT INTO `chat_history` VALUES (419, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '我刚完成了「症状自评量表（SCL-90）」，结果是「中度风险」（约 60%）。想请你帮我一起看看接下来可以怎么调整。', '2026-04-15 16:13:27');
INSERT INTO `chat_history` VALUES (420, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '好的，那我们重新开始聊 ☺️\n\n---\n\n先说一句：做完量表后看到\"中度风险\"这几个字，心里多少会有点紧张吧？\n\n其实这个结果更像是一个提醒——\"嘿，最近可能需要多关心一下自己了\"，而不是什么定论。\n\n---\n\n我想先听听你的感受：\n\n**看到这个结果的时候，你第一反应是什么？**\n\n是\"果然如此\"，还是有点意外？\n\n或者你现在心里有什么想说的，都可以直接告诉我，我们慢慢聊 🌿', '2026-04-15 16:13:34');
INSERT INTO `chat_history` VALUES (421, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '来一段100字的小文章', '2026-04-15 16:16:07');
INSERT INTO `chat_history` VALUES (422, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '好的，给你写一段 ☺️\n\n---\n\n**给最近有点累的你**\n\n生活有时候像一场没有彩排的演出，我们都在边走边学。\n\n偶尔感到疲惫、迷茫、甚至有点丧，都很正常。那不是软弱，是身体在提醒你：该停下来，抱抱自己了。\n\n不必每天都闪闪发光，允许自己偶尔暗淡一点。\n\n你已经做得很好了，真的。\n\n---\n\n如果你想要其他主题的文章，也可以告诉我 🌿', '2026-04-15 16:16:18');
INSERT INTO `chat_history` VALUES (423, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '来一段200字的', '2026-04-15 16:16:40');
INSERT INTO `chat_history` VALUES (424, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '好的，继续为你写 ☺️\n\n---\n\n**允许自己慢慢来**\n\n我们总是被催促着往前跑——要优秀、要坚强、要懂事。\n\n可是没有人告诉我们，累了可以停下来，难过了可以哭出来，不想说话的时候也可以安静待着。\n\n你不需要时刻都完美。偶尔的脆弱，不是失败，而是你在认真感受生活。\n\n那些深夜的辗转、莫名的低落、说不出口的委屈，都是真实的你，都值得被温柔以待。\n\n成长从来不是一条直线，它更像是螺旋——有时候觉得自己在原地打转，但回头看看，其实已经走了很远。\n\n所以，别太苛责自己。\n\n今天的你，能撑到现在，已经很了不起了。\n\n明天的事，明天再说。\n\n今晚，就让自己好好休息吧 🌙\n\n---\n\n还想听什么主题的，随时告诉我 🌿', '2026-04-15 16:16:47');
INSERT INTO `chat_history` VALUES (425, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '再来一段', '2026-04-15 16:17:04');
INSERT INTO `chat_history` VALUES (426, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '好的，继续为你写 ☺️\n\n---\n\n**你不必和任何人比较**\n\n看着别人闪闪发光，难免会觉得自己黯淡无光。\n\n可是你知道吗，每个人都有自己的时区。\n\n有人二十岁就找到方向，有人三十岁才开始探索，有人四十岁才迎来转机——这些都没有错。\n\n你看到的只是别人的高光时刻，那些深夜的焦虑、独自扛过的难关，谁都不会轻易展示。\n\n你走的每一步，都在塑造独一无二的自己。\n\n那些弯路、那些跌倒、那些看似浪费的时间，其实都在悄悄积累成你的底气。\n\n所以，别总盯着别人的赛道。\n\n你的路，只有你自己能走。\n\n慢一点也没关系，走得稳，才能走得远。\n\n你不需要成为任何人，做你自己就够了 🌻\n\n---\n\n还想继续听吗？或者有什么想聊的，我都在 🌿', '2026-04-15 16:17:13');
INSERT INTO `chat_history` VALUES (427, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '再来一段', '2026-04-15 16:17:27');
INSERT INTO `chat_history` VALUES (428, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '好的，继续为你写 ☺️\n\n---\n\n**那些说不出口的难过**\n\n有时候，最累的不是事情本身，而是假装没事。\n\n明明心里堵得慌，却笑着说\"我很好\"。\n\n明明想被理解，却不知道从何说起。\n\n明明很需要一个拥抱，却只能自己抱抱自己。\n\n你有没有发现，我们总是习惯把脆弱藏起来，怕给别人添麻烦，怕被说矫情，怕没有人真的在乎。\n\n可是，难过就是难过，不需要理由，也不需要向谁证明。\n\n你的情绪是真实的，它值得被看见，被承认，被温柔对待。\n\n如果此刻的你正在经历什么，我想告诉你：\n\n你不需要一个人扛着。\n\n想哭就哭，想说就说，想安静就安静。\n\n你已经很努力了，真的。\n\n那些熬过的夜、咽下的委屈、独自撑过的时刻，我都看见了。\n\n你很棒，你值得被好好爱着 💛\n\n---\n\n还有想听的吗？我一直都在 🌿', '2026-04-15 16:17:35');
INSERT INTO `chat_history` VALUES (429, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'user', '再来', '2026-04-15 16:18:44');
INSERT INTO `chat_history` VALUES (430, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '好的，继续为你写 ☺️\n\n---\n\n**你可以休息的**\n\n你是不是总觉得，不能停下来？\n\n好像一休息就是偷懒，一放松就是落后。\n\n手机不敢放下，觉不敢多睡，连发呆都觉得是浪费时间。\n\n可是，你不是机器啊。\n\n你会累，会倦，会想躲起来什么都不做。\n\n这些都很正常。\n\n弦绷得太紧会断，人绷得太紧会垮。\n\n休息不是放弃，是为了走更远的路。\n\n今天不想学习，那就放一放。\n\n今天只想躺着，那就躺一会儿。\n\n今天什么都不想做，那就什么都不做。\n\n你不需要时刻都在努力，偶尔的停顿，也是生活的一部分。\n\n给自己一点喘息的空间吧。\n\n你已经够辛苦了，值得被温柔以待。\n\n允许自己休息，也是一种勇敢 🌙\n\n---\n\n还想听吗？或者想聊聊别的，我都在 🌿', '2026-04-15 16:18:57');
