INSERT INTO `chat_history` VALUES (434, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 'assistant', '抱歉抱歉！刚才那条回复有点奇怪，我重新来 ☺️\n\n---\n\n你想聊什么呢？\n\n可以聊聊最近的心情，说说学习或生活中的烦恼，或者只是想有人陪着说说话。\n\n我都在，慢慢来，不着急 🌿\n\n---\n\n或者你有什么想问我的也行，比如：\n\n- 最近压力很大怎么办\n- 和朋友/室友相处有点累\n- 感觉自己不够好\n- 睡不好、吃不好\n- 想聊聊某件事但不知道找谁说\n- 或者就是单纯想有人听你说说话\n\n你愿意的话，从哪里开始都可以 💙', '2026-04-15 16:23:01');
