INSERT INTO `quiz_result` VALUES (11, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 4, '[{\"questionId\": 20, \"selectedOptionIndex\": 2}, {\"questionId\": 36, \"selectedOptionIndex\": 2}, {\"questionId\": 21, \"selectedOptionIndex\": 2}, {\"questionId\": 37, \"selectedOptionIndex\": 2}, {\"questionId\": 22, \"selectedOptionIndex\": 3}, {\"questionId\": 38, \"selectedOptionIndex\": 2}, {\"questionId\": 23, \"selectedOptionIndex\": 1}, {\"questionId\": 39, \"selectedOptionIndex\": 1}, {\"questionId\": 24, \"selectedOptionIndex\": 1}, {\"questionId\": 40, \"selectedOptionIndex\": 2}, {\"questionId\": 25, \"selectedOptionIndex\": 3}, {\"questionId\": 41, \"selectedOptionIndex\": 3}, {\"questionId\": 26, \"selectedOptionIndex\": 2}, {\"questionId\": 42, \"selectedOptionIndex\": 0}]', 26, 42, 62, '高风险', '当前测评提示风险偏高，请优先关注自身安全，并尽快联系可信任的人或专业机构。\n在获得专业支持前，可先使用驿站与树洞进行情绪疏导，但不应替代面对面评估。\n如出现自伤念头，请立即拨打当地紧急求助电话或前往医院急诊。', '我刚完成了「GAD-7 教学演示版」，结果是「高风险」（约 62%）。想请你帮我一起看看接下来可以怎么调整。', '解读摘要\n你的测评结果显示，近期你的情绪可能正经历着比较明显的困扰与担忧。这并不代表你“有问题”或“不够好”，它只是一个信号，提醒你需要多关注一下自己的内心状态，并考虑寻求一些支持。请记住，感受到压力是正常的，而主动面对它，正是关爱自己的开始。\n\n行动建议\n· 如果脑海中出现伤害自己的念头，请立刻将安全放在第一位，拨打心理援助热线（如：010-82951332）或前往医院心理科/急诊科。\n· 尝试找一位你信任的家人或朋友，坦诚地聊聊你的感受。倾诉本身就有很大的力量，或者你也可以在专业的线上树洞平台进行表达。\n· 当感到焦虑席卷而来时，可以尝试一个简单的“着陆练习”：深呼吸，然后说出你看到的5样东西、触摸到的4样东西、听到的3种声音、闻到的2种气味和尝到的1种味道，帮助自己回到当下。\n· 在情绪稍微平稳的阶段，请为自己安排一件简单、愉快的小事，比如听一首喜欢的歌、短距离散步、洗个热水澡，专注完成这个瞬间。\n· 尽快考虑预约学校的心理咨询中心、医院的心理科或正规心理咨询机构。让专业人士陪你一起梳理，这是非常重要且有效的自我关怀步骤。\n\n（以上内容仅供自我调节参考，不能替代专业的医学诊断与治疗。）', '2026-04-13 15:18:11');
