INSERT INTO `quiz_result` VALUES (13, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 4, '[{\"questionId\": 20, \"selectedOptionIndex\": 2}, {\"questionId\": 36, \"selectedOptionIndex\": 2}, {\"questionId\": 21, \"selectedOptionIndex\": 2}, {\"questionId\": 37, \"selectedOptionIndex\": 2}, {\"questionId\": 22, \"selectedOptionIndex\": 3}, {\"questionId\": 38, \"selectedOptionIndex\": 2}, {\"questionId\": 23, \"selectedOptionIndex\": 1}, {\"questionId\": 39, \"selectedOptionIndex\": 1}, {\"questionId\": 24, \"selectedOptionIndex\": 1}, {\"questionId\": 40, \"selectedOptionIndex\": 2}, {\"questionId\": 25, \"selectedOptionIndex\": 3}, {\"questionId\": 41, \"selectedOptionIndex\": 3}, {\"questionId\": 26, \"selectedOptionIndex\": 2}, {\"questionId\": 42, \"selectedOptionIndex\": 0}]', 26, 42, 62, '高风险', '当前测评提示风险偏高，请优先关注自身安全，并尽快联系可信任的人或专业机构。\n在获得专业支持前，可先使用驿站与树洞进行情绪疏导，但不应替代面对面评估。\n如出现自伤念头，请立即拨打当地紧急求助电话或前往医院急诊。', '我刚完成了「GAD-7 教学演示版」，结果是「高风险」（约 62%）。想请你帮我一起看看接下来可以怎么调整。', '解读摘要\n你的测评结果提示可能存在较高的焦虑感受。这段时间你可能承受着较大的心理压力，情绪容易感到紧张或担忧。请记得，这个分数只是一个参考信号，重要的是它提醒你需要多关注和照顾自己。你愿意面对并探索这些感受，本身就是一种勇敢的开始。\n\n行动建议\n· 主动联系一位你信任的师长、朋友或家人，和他们聊聊你最近的感受。\n· 了解并保存本地专业资源的联系方式，如学校心理咨询中心或正规医疗机构的心理科。\n· 尝试每天进行10-15分钟的放松练习，例如正念呼吸或情绪记录，帮助自己平稳情绪。\n· 如果脑海中出现伤害自己的念头，请立即停止独自承受，务必拨打紧急求助电话或前往医院。\n· 请记住，以上所有建议仅供自我调节参考，不能替代专业的心理评估与诊疗。', '2026-04-13 15:18:49');
INSERT INTO `quiz_result` VALUES (14, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 4, '[{\"questionId\": 20, \"selectedOptionIndex\": 2}, {\"questionId\": 36, \"selectedOptionIndex\": 2}, {\"questionId\": 21, \"selectedOptionIndex\": 2}, {\"questionId\": 37, \"selectedOptionIndex\": 2}, {\"questionId\": 22, \"selectedOptionIndex\": 2}, {\"questionId\": 38, \"selectedOptionIndex\": 2}, {\"questionId\": 23, \"selectedOptionIndex\": 1}, {\"questionId\": 39, \"selectedOptionIndex\": 1}, {\"questionId\": 24, \"selectedOptionIndex\": 2}, {\"questionId\": 40, \"selectedOptionIndex\": 1}, {\"questionId\": 25, \"selectedOptionIndex\": 2}, {\"questionId\": 41, \"selectedOptionIndex\": 2}, {\"questionId\": 26, \"selectedOptionIndex\": 2}, {\"questionId\": 42, \"selectedOptionIndex\": 2}]', 25, 42, 60, '高风险', '当前测评提示风险偏高，请优先关注自身安全，并尽快联系可信任的人或专业机构。\n在获得专业支持前，可先使用驿站与树洞进行情绪疏导，但不应替代面对面评估。\n如出现自伤念头，请立即拨打当地紧急求助电话或前往医院急诊。', '我刚完成了「GAD-7 教学演示版」，结果是「高风险」（约 60%）。想请你帮我一起看看接下来可以怎么调整。', '解读摘要  \n根据你的测评结果，得分25分（满分42分），占比60%，这提示你当前的焦虑情绪可能较为明显，需要多加关注。请记住，这只是一个自我参考工具，不能替代专业诊断，我们可以一起用温和的方式照顾你的情绪健康。建议你优先考虑自身安全，并尝试一些自我调节方法。\n\n行动建议  \n1. 尝试与信任的朋友、家人或老师聊聊你的感受，获得情感支持。  \n2. 利用校园驿站或树洞等匿名渠道进行情绪疏导，释放压力。  \n3. 练习放松技巧，如深呼吸、冥想或温和运动，帮助缓解紧张情绪。  \n4. 保持规律作息和健康饮食，为身心提供稳定基础。  \n5. 如出现任何不安全或自伤念头，请立即联系紧急服务或前往医院寻求帮助。  \n\n（内容仅供自我调节参考，不可替代专业诊疗）', '2026-04-13 15:25:40');
INSERT INTO `quiz_result` VALUES (15, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 4, '[{\"questionId\": 20, \"selectedOptionIndex\": 2}, {\"questionId\": 36, \"selectedOptionIndex\": 2}, {\"questionId\": 21, \"selectedOptionIndex\": 2}, {\"questionId\": 37, \"selectedOptionIndex\": 2}, {\"questionId\": 22, \"selectedOptionIndex\": 2}, {\"questionId\": 38, \"selectedOptionIndex\": 1}, {\"questionId\": 23, \"selectedOptionIndex\": 1}, {\"questionId\": 39, \"selectedOptionIndex\": 2}, {\"questionId\": 24, \"selectedOptionIndex\": 2}, {\"questionId\": 40, \"selectedOptionIndex\": 1}, {\"questionId\": 25, \"selectedOptionIndex\": 1}, {\"questionId\": 41, \"selectedOptionIndex\": 2}, {\"questionId\": 26, \"selectedOptionIndex\": 2}, {\"questionId\": 42, \"selectedOptionIndex\": 1}]', 23, 42, 55, '高风险', '当前测评提示风险偏高，请优先关注自身安全，并尽快联系可信任的人或专业机构。\n在获得专业支持前，可先使用驿站与树洞进行情绪疏导，但不应替代面对面评估。\n如出现自伤念头，请立即拨打当地紧急求助电话或前往医院急诊。', '我刚完成了「GAD-7 教学演示版」，结果是「高风险」（约 55%）。想请你帮我一起看看接下来可以怎么调整。', '解读摘要\n你的测评结果显示焦虑水平相对较高，这可能反映了你近期正承受着较大的情绪压力。请记得，这样的感受并不孤单，许多人都会经历类似的困扰。重要的是，你现在意识到了这一点，并可以开始采取一些温和的步骤来关怀自己。我们鼓励你优先关注内心的安全感，并思考如何寻求适当的支持。\n\n行动建议\n1. 尝试简单的放松技巧：每天花5-10分钟进行深呼吸或冥想练习，帮助缓解紧张情绪。\n2. 与信任的人交流感受：找一位朋友或家人谈谈你的想法，分享可以减轻心理负担。\n3. 建立规律的生活节奏：确保充足的睡眠、均衡饮食和适度运动，以稳定情绪基础。\n4. 参与愉悦的自我照顾活动：比如听音乐、散步或写日记，给自己一些轻松的时间。\n5. 记录情绪变化：用笔记本或手机应用简单记录每天的心情，帮助识别触发因素。\n\n请注意，以上内容仅供自我调节参考，不能替代专业的心理评估或诊疗。如果你感到极度困扰或安全受到威胁，请务必及时联系专业机构或紧急服务。', '2026-04-13 15:34:05');
