INSERT INTO `quiz_result` VALUES (35, 'oCH0C7nN1jmK-lvOMvHnqsZ1OWc8', 4, '[{\"questionId\": 20, \"selectedOptionIndex\": 0}, {\"questionId\": 36, \"selectedOptionIndex\": 2}, {\"questionId\": 21, \"selectedOptionIndex\": 2}, {\"questionId\": 37, \"selectedOptionIndex\": 2}, {\"questionId\": 22, \"selectedOptionIndex\": 1}, {\"questionId\": 38, \"selectedOptionIndex\": 2}, {\"questionId\": 23, \"selectedOptionIndex\": 1}, {\"questionId\": 39, \"selectedOptionIndex\": 0}, {\"questionId\": 24, \"selectedOptionIndex\": 2}, {\"questionId\": 40, \"selectedOptionIndex\": 1}, {\"questionId\": 25, \"selectedOptionIndex\": 1}, {\"questionId\": 41, \"selectedOptionIndex\": 1}, {\"questionId\": 26, \"selectedOptionIndex\": 2}, {\"questionId\": 42, \"selectedOptionIndex\": 2}]', 19, 42, 45, '高风险', '当前测评提示风险偏高，请优先关注自身安全，并尽快联系可信任的人或专业机构。\n在获得专业支持前，可先使用驿站与树洞进行情绪疏导，但不应替代面对面评估。\n如出现自伤念头，请立即拨打当地紧急求助电话或前往医院急诊。', '我刚完成了「GAD-7 教学演示版」，结果是「高风险」（约 45%）。想请你帮我一起看看接下来可以怎么调整。', '解读摘要\n测评结果显示，你可能正经历着较为明显的焦虑情绪，这些感受在近期对你的影响比较大。请记得，这只是一个参考信号，它帮助我们更了解自己的状态，而不是对你个人的定义。你愿意关注自己的内心感受，这本身就是非常勇敢和积极的一步。\n\n行动建议\n1.  尝试每天用5分钟记录情绪触发点，简单写下“什么事让我感到紧张”，这有助于梳理情绪来源。\n2.  当感到焦虑时，可以尝试“478呼吸法”：用鼻子吸气4秒，屏息7秒，用嘴缓缓呼气8秒，重复几次。\n3.  主动联系一位你信任的朋友或家人，不一定要谈论烦恼，简单地聊聊天或一起散散步也能带来支持感。\n4.  建立稳定的作息节奏，尤其保证睡眠，避免在睡前接触过多令人紧张的信息。\n5.  考虑预约学校的心理咨询中心，与专业人士进行一次面对面交流，获得更个性化的支持。\n\n（温馨提示：以上内容仅供自我调节参考，不能替代专业的心理评估与诊疗。如果你感到难以承受，请务必及时寻求专业帮助。）', '2026-04-14 14:22:05');
